mermaid.text:
flowchart TD
  Start["post-review facts"] --> BlockedCommit{"commit gate blocked?"}
  BlockedCommit -->|yes| Continuation["continuation-inference / blocker"]
  BlockedCommit -->|no| MissingCommit{"source changed + no commit evidence?"}
  MissingCommit -->|yes| CommitIntent["commit-intent"]
  MissingCommit -->|no| BlockedPR{"PR gate blocked?"}
  BlockedPR -->|yes| Continuation
  BlockedPR -->|no| MissingPR{"PR required + missing?"}
  MissingPR -->|yes| PRReview["pr-review"]
  MissingPR -->|no| Imbalance{"doc imbalance?"}
  Imbalance -->|yes| Balance["living-doc-balance-scan"]
  Imbalance -->|no| ClosureReady{"closure ready?"}
  ClosureReady -->|yes| Closure["closure-review"]
  ClosureReady -->|no| Worker["worker continuation or explicit blocker"]
